import React, { useState, useEffect } from 'react';
import Header from '../components/common/Header';
import Sidebar from '../components/common/Sidebar';
import ProjectList from '../components/projects/ProjectList';
import CreateProject from '../components/projects/CreateProject';
import { projectAPI } from '../services/api';
import ProjectDetail from './ProjectDetail';

const Dashboard = ({ user, onLogout }) => {
  const [projects, setProjects] = useState([]);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchProjects();
  }, []);

  const fetchProjects = async () => {
    try {
      const response = await projectAPI.getAll();
      setProjects(response.data);
      setError('');
    } catch (error) {
      console.error('Error fetching projects:', error);
      setError('Failed to load projects');
    } finally {
      setLoading(false);
    }
  };

  const handleProjectCreated = (newProject) => {
    setProjects([newProject, ...projects]);
    setShowCreateForm(false);
    setError('');
  };

  const handleCreateError = (errorMessage) => {
    setError(errorMessage);
  };

  const stats = {
    totalProjects: projects.length,
    totalTasks: projects.reduce((acc, project) => acc + (project.task_count || 0), 0),
    completedTasks: projects.reduce((acc, project) => acc + (project.completed_tasks || 0), 0)
  };

  return (
    <div className="dashboard">
      <Sidebar />
      
      <div className="main-content">
        <Header user={user} onLogout={onLogout} />
        
        {error && (
          <div className="error-message" style={{marginBottom: '1rem'}}>
            {error}
          </div>
        )}
        
        {/* Stats Overview */}
        <div className="grid grid-3">
          <div className="card stat-card">
            <div className="stat-icon">📁</div>
            <div className="stat-content">
              <h3>{stats.totalProjects}</h3>
              <p>Total Projects</p>
            </div>
          </div>
          
          <div className="card stat-card">
            <div className="stat-icon">✅</div>
            <div className="stat-content">
              <h3>{stats.totalTasks}</h3>
              <p>Total Tasks</p>
            </div>
          </div>
          
          <div className="card stat-card">
            <div className="stat-icon">🎯</div>
            <div className="stat-content">
              <h3>{stats.completedTasks}</h3>
              <p>Completed</p>
            </div>
          </div>
        </div>

        {/* Projects Section */}
        <div className="card">
          <div className="card-header">
            <h3 className="card-title">Your Projects</h3>
            <button 
              className="btn btn-primary"
              onClick={() => setShowCreateForm(!showCreateForm)}
              disabled={loading}
            >
              {showCreateForm ? 'Cancel' : '+ New Project'}
            </button>
          </div>

          {showCreateForm && (
            <div className="create-project-container">
              <CreateProject 
                onProjectCreated={handleProjectCreated}
                onCancel={() => setShowCreateForm(false)}
                onError={handleCreateError}
              />
            </div>
          )}

          {loading ? (
            <div className="loading">Loading projects...</div>
          ) : (
            <ProjectList projects={projects} />
          )}
        </div>

        {/* Recent Activity */}
        <div className="card">
          <div className="card-header">
            <h3 className="card-title">Recent Activity</h3>
          </div>
          <div className="activity-list">
            {projects.length === 0 ? (
              <p className="empty-activity">No recent activity. Create a project to get started!</p>
            ) : (
              <div>
                <p><strong>Recent Projects:</strong></p>
                <ul>
                  {projects.slice(0, 3).map(project => (
                    <li key={project.id} style={{marginBottom: '0.5rem'}}>
                      🆕 Created "{project.name}" - {new Date(project.created_at).toLocaleDateString()}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
